const {fitDataAsync, OPTIMIZERS} = DataScience;
const dimensions = 50;
const latentDimensions = 10;
const epochs = 2000;
const batchSize = 100;
const status = document.createElement("div");
status.style.maxWidth = "512px";
status.style.whiteSpace = "normal";
status.style.overflowWrap = "anywhere";
status.textContent = "Loading celebrity faces...";

const image = IO.paintCelebrityFace(new Float32Array(32 * 32 * 3), 16);
const latentCoords = new Array(latentDimensions).fill(0);
let pca;
let decoder;
let ready = false;

const updateImage = () => {
    const input = Object.fromEntries(latentCoords.map((value, i) => [`x_${i}`, value]));
    const decoded = decoder.compiledNN({...input, ...decoder.weightsMap});
    if (decoded.some(value => !Number.isFinite(value))) throw new Error("Decoder produced non-finite values");
    image.update(new Float32Array(pca.gen(decoded).toArray()));
};

const sliders = Array.from({length: latentDimensions}, (_, i) => ({
    type: "slider",
    value: () => ({
        min: -3,
        max: 3,
        value: 0,
        title: `w_${i + 1}`,
        onChange: value => {
            latentCoords[i] = value;
            if (ready) {
                try {
                    updateImage();
                } catch (error) {
                    console.error("Could not update face:", error);
                    status.textContent = `Could not update face: ${error.message}`;
                }
            }
        },
    }),
}));
const ui = IO.UI(
    {type: "canvas", value: () => status},
    {type: "canvas", value: () => image},
    ...sliders,
);

const initialize = async () => {
    const samples = await IO.loadCelebrityFaces(200);
    if (samples.length <= dimensions) throw new Error("At least 51 faces are required");
    status.textContent = "Computing 50 PCA components for 32x32 RGB faces; this may take a while...";
    await new Promise(resolve => setTimeout(resolve, 0));
    pca = PCA.new(samples, dimensions);
    if (pca.principalValues.some(value => !Number.isFinite(value) || value <= 0)) {
        throw new Error("PCA could not find enough nonzero components");
    }
    const coordinates = samples.map(sample => pca.proj(sample));
    if (coordinates.some(point => point.some(value => !Number.isFinite(value)))) {
        throw new Error("PCA produced non-finite coordinates");
    }

    status.textContent = "Preparing autoencoder...";
    await new Promise(resolve => setTimeout(resolve, 0));
    const autoencoder = NeuralNet.builder()
        .input(dimensions)
        .layer(latentDimensions)
        .layer(dimensions, NeuralNet.ACTIVATIONS.linear)
        .build();
    const {theta} = await fitDataAsync(coordinates, coordinates, autoencoder.model, {
        epochs,
        batch: batchSize,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.003}),
        continuationEvery: 50,
        continuationFn: ({epoch, loss}) => {
            const progress = `Training: ${epoch + 1}/${epochs} (mini-batch loss ${loss.toFixed(4)})`;
            status.textContent = progress;
            console.log(progress);
        },
    });

    status.textContent = "Setting up decoder...";
    await new Promise(resolve => setTimeout(resolve, 0));
    decoder = NeuralNet.builder()
        .input(latentDimensions)
        .layer(dimensions, NeuralNet.ACTIVATIONS.linear)
        .build();
    const decoderWeights = {};
    for (const key of Object.keys(decoder.weightsMap)) {
        const source = key.replace(/^W0_/, "W1_").replace(/^b0_/, "b1_");
        if (!(source in theta)) throw new Error(`Missing trained decoder weight: ${source}`);
        if (!Number.isFinite(theta[source])) throw new Error(`Non-finite trained decoder weight: ${source}`);
        decoderWeights[key] = theta[source];
    }
    decoder.setWeights(decoderWeights);

    updateImage();
    ready = true;
    status.textContent = "Ready. Use sliders to explore the bottleneck space.";
};
setTimeout(() => {
    initialize().catch(error => {
        console.error("Could not initialize celebrity faces autoencoder:", error);
        status.textContent = `Could not initialize celebrity faces autoencoder: ${error.message}`;
    });
}, 0);
ui;
